#include <ctype.h>
#include <setjmp.h>
#include <stdio.h>
#include <string.h>

static jmp_buf on_error;
static const char *text;
static size_t pos;
static size_t error_pos;
static long long sum;
static int max_depth;

static void fail(void) {
    error_pos = pos + 1;
    longjmp(on_error, 1);
}

static void skip_spaces(void) {
    while (text[pos] == ' ') {
        pos++;
    }
}

static void parse_list(int depth, volatile int *numbers) {
    if (depth > max_depth) {
        max_depth = depth;
    }
    pos++;                                    // открывающая скобка
    for (;;) {
        skip_spaces();
        char c = text[pos];
        if (c == ')') {
            pos++;
            return;
        }
        if (c == '(') {
            parse_list(depth + 1, numbers);
        } else if (isdigit((unsigned char)c)) {
            long long value = 0;
            while (isdigit((unsigned char)text[pos])) {
                value = value * 10 + (text[pos] - '0');
                pos++;
            }
            sum += value;
            (*numbers)++;
        } else {
            fail();
        }
    }
}

static void check_line(const char *line) {
    volatile int numbers = 0;
    text = line;
    pos = 0;
    sum = 0;
    max_depth = 0;
    if (setjmp(on_error) == 0) {
        if (text[pos] != '(') {
            fail();
        }
        parse_list(1, &numbers);
        skip_spaces();
        if (text[pos] != '\0') {
            fail();
        }
        printf("сумма %lld, глубина %d\n", sum, max_depth);
    } else {
        printf("ошибка в позиции %zu после %d чисел\n", error_pos, numbers);
    }
}

int main(void) {
    char line[256];
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\r\n")] = '\0';
        check_line(line);
    }
    return 0;
}

