#include <signal.h>
#include <stdio.h>

static volatile sig_atomic_t hits = 0;

static void handler(int sig) {
    signal(sig, handler);       // переустановить: реакция могла сброситься
    hits = hits + 1;
}

int main(void) {
    signal(SIGINT, handler);
    raise(SIGINT);
    raise(SIGINT);
    printf("%d\n", (int)hits);
    return 0;
}
